#!/usr/bin/env bash
#
#### THIS FILE IS MANAGED BY AN AUTOMATED WORKFLOW ####
#### UPDATES MUST BE DONE IN THE CI-WORKFLOWS REPO - OR YOUR CHANGES WILL BE LOST ####
#### https://github.com/next-mesh/ci-workflows ####
#
# Writes a markdown table of useful job context to $GITHUB_STEP_SUMMARY.
# https://github.blog/2022-05-09-supercharging-github-actions-with-job-summaries/
#
# Usage (after actions/checkout):
#   - name: Step summary
#     if: always()
#     run: .github/actions-scripts/output-job-summary.sh
#     shell: bash
#     env:
#       ADDITIONAL_OUTPUTS: "Env=${{ inputs.environment }},AwsAccount=${{ inputs.aws_account_id }}"
#       DEBUG: "false"

set -euo pipefail

rows=(
  "Repository"
  "Github Actor"
  "Github Ref"
  "Github Ref Type"
  "Git SHA"
  "Github Target Branch (Base Ref)"
  "Github Workflow Ref"
  "Github Runner Name"
)

env_vars=(
  "GITHUB_REPOSITORY"
  "GITHUB_ACTOR"
  "GITHUB_REF"
  "GITHUB_REF_TYPE"
  "GITHUB_SHA"
  "GITHUB_BASE_REF"
  "GITHUB_WORKFLOW_REF"
  "RUNNER_NAME"
)

build_table() {
  local tz
  tz="${TZ:-Australia/Sydney}"
  table="| Job Summary | $(TZ="$tz" date) |\n| --- | --- |\n"

  for i in "${!rows[@]}"; do
    local row="${rows[$i]}"
    local env_var="${env_vars[$i]}"
    local value="${!env_var:-}"
    if [ -n "$value" ]; then
      table+="| $row | $value |\n"
    fi
  done

  # ADDITIONAL_OUTPUTS: comma-separated K=V pairs
  if [ -n "${ADDITIONAL_OUTPUTS:-}" ]; then
    IFS=',' read -ra pairs <<<"$ADDITIONAL_OUTPUTS"
    for pair in "${pairs[@]}"; do
      IFS='=' read -ra kv <<<"$pair"
      local key="${kv[0]:-}"
      local value="${kv[1]:-}"
      if [ -n "$key" ] && [ -n "$value" ]; then
        table+="| $key | $value |\n"
      fi
    done
  fi

  # Pick up anything else exposed as INPUT_*
  for env_var in $(env | grep -E '^INPUT_' | cut -d '=' -f 1); do
    local value="${!env_var:-}"
    if [ -n "$value" ]; then
      table+="| ${env_var#INPUT_} | $value |\n"
    fi
  done

  table+="| Runner Uptime | $(uptime) |\n"
}

debug_dump() {
  {
    echo "Debug mode enabled"
    env | sort
    echo
  } >> "$GITHUB_STEP_SUMMARY"
}

build_table

if [ "${DEBUG:-false}" = "true" ]; then
  debug_dump
fi

{
  echo -e "## Step Summary\n"
  echo -e "$table"
  echo
  echo "_Generated by output-job-summary.sh — sourced from next-mesh/ci-workflows_"
} >> "$GITHUB_STEP_SUMMARY"
